insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q1', 'g9_math_l1', 'numeric', 1, 'حل المعادلة: س + 7 = 12. ما قيمة س؟', null, '5'::jsonb, null, null, 0.001, null, 'س = 12 − 7 = 5.', null, null, 0) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q2', 'g9_math_l1', 'numeric', 1, 'حل المعادلة: 3س = 21. ما قيمة س؟', null, '7'::jsonb, null, null, 0.001, null, 'س = 21 ÷ 3 = 7.', null, null, 1) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q3', 'g9_math_l1', 'numeric', 2, 'حل المعادلة: 2س + 3 = 11. ما قيمة س؟', null, '4'::jsonb, null, null, 0.001, null, '2س = 8 ← س = 4.', null, null, 2) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q4', 'g9_math_l1', 'mcq', 2, 'ما الخطوة الأولى المناسبة لحل 4س − 5 = 15؟', array['قسمة الطرفين على 4','جمع 5 إلى الطرفين','طرح 15 من الطرفين']::text[], '1'::jsonb, null, null, null, null, 'نتخلص من الحد الثابت أولًا بجمع 5: 4س = 20.', null, null, 3) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q5', 'g9_math_l1', 'trueFalse', 2, 'س = 3 حل للمعادلة 5س − 4 = 11.', null, 'true'::jsonb, null, null, null, null, '5(3) − 4 = 15 − 4 = 11 ✓', null, null, 4) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q6', 'g9_math_l1', 'numeric', 3, 'حل المعادلة: 5س − 7 = 3س + 9. ما قيمة س؟', null, '8'::jsonb, null, null, 0.001, null, '2س = 16 ← س = 8.', null, null, 5) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q7', 'g9_math_l1', 'numeric', 4, 'عمر أحمد الآن س سنة، وبعد 6 سنوات يصبح عمره ضعف عمره قبل سنة واحدة. ما قيمة س؟', null, '8'::jsonb, null, null, 0.001, null, 'س + 6 = 2(س − 1) ← س + 6 = 2س − 2 ← س = 8.', null, null, 6) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l1_q8', 'g9_math_l1', 'essay', 3, 'اشرح لماذا يجب إجراء العملية نفسها على طرفي المعادلة.', null, null, null, null, null, null, null, 'لأن المعادلة تمثل توازنًا بين طرفين متساويين، وإجراء العملية نفسها على الطرفين يحافظ على التساوي.', null, 7) on conflict (id) do nothing;
