insert into lessons (id, unit_id, title, objectives, explanation, examples, key_points, summary, video_url, book_page, sort, published) values ('g9_math_l2', 'g9_math_u2', 'نظرية فيثاغورس', array['أتعرّف نظرية فيثاغورس.','أحسب طول ضلع مجهول في مثلث قائم الزاوية.']::text[], 'في المثلث القائم الزاوية يسمى الضلع المقابل للزاوية القائمة «الوتر»، وهو أطول الأضلاع.
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q1', 'g9_math_l2', 'trueFalse', 1, 'الوتر هو أطول أضلاع المثلث القائم الزاوية.', null, 'true'::jsonb, null, null, null, null, 'الوتر يقابل الزاوية القائمة وهي أكبر زاوية.', null, null, 0) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q2', 'g9_math_l2', 'numeric', 2, 'مثلث قائم الزاوية طولا ضلعيه 6 سم و 8 سم. ما طول الوتر؟', null, '10'::jsonb, null, null, 0.001, 'سم', 'جـ² = 36 + 64 = 100 ← جـ = 10 سم.', null, null, 1) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q3', 'g9_math_l2', 'numeric', 2, 'مثلث قائم الزاوية وتره 13 سم وأحد ضلعيه 5 سم. ما طول الضلع الآخر؟', null, '12'::jsonb, null, null, 0.001, 'سم', 'ب² = 169 − 25 = 144 ← ب = 12 سم.', null, null, 2) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q4', 'g9_math_l2', 'mcq', 2, 'في المثلث القائم المرسوم: الضلع الرأسي 3 وحدات والقاعدة 4 وحدات (كل علامة زرقاء تفصل وحدة). ما طول الوتر الملوّن بالأحمر؟', array['7','5','12','25']::text[], '1'::jsonb, null, null, null, null, 'جـ² = 3² + 4² = 25 ← جـ = 5.', null, 'images/right_triangle.png', 3) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q5', 'g9_math_l2', 'mcq', 3, 'أيّ الثلاثيات التالية يمكن أن تكون أطوال أضلاع مثلث قائم؟', array['4، 5، 6','5، 12، 13','2، 3، 4','6، 7، 9']::text[], '1'::jsonb, null, null, null, null, '25 + 144 = 169 = 13².', null, null, 4) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_math_l2_q6', 'g9_math_l2', 'numeric', 4, 'سلّم طوله 10 أمتار يستند إلى جدار، وبُعد أسفله عن الجدار 6 أمتار. على أي ارتفاع يلامس الجدار؟', null, '8'::jsonb, null, null, 0.001, 'م', 'الارتفاع² = 100 − 36 = 64 ← الارتفاع = 8 م.', null, null, 5) on conflict (id) do nothing;
