insert into lessons (id, unit_id, title, objectives, explanation, examples, key_points, summary, video_url, book_page, sort, published) values ('g9_science_l1', 'g9_science_u1', 'قانون نيوتن الأول (القصور الذاتي)', array['أنص على قانون نيوتن الأول.','أفسّر مواقف حياتية باستخدام مفهوم القصور الذاتي.']::text[], 'ينص قانون نيوتن الأول على أن: الجسم الساكن يبقى ساكنًا، والجسم المتحرك يبقى متحركًا بسرعة ثابتة وفي خط مستقيم، ما لم تؤثر فيه قوة محصلة تغيّر حالته.
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_science_l1_q1', 'g9_science_l1', 'trueFalse', 1, 'الجسم الساكن يبقى ساكنًا ما لم تؤثر فيه قوة محصلة.', null, 'true'::jsonb, null, null, null, null, 'هذا نص قانون نيوتن الأول.', null, null, 0) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_science_l1_q2', 'g9_science_l1', 'mcq', 1, 'يسمى ميل الجسم إلى مقاومة التغير في حالته الحركية:', array['التسارع','القصور الذاتي','الوزن','الاحتكاك']::text[], '1'::jsonb, null, null, null, null, 'هذا تعريف القصور الذاتي.', null, null, 1) on conflict (id) do nothing;
insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_science_l1_q3', 'g9_science_l1', 'mcq', 2, 'لماذا يندفع الركاب إلى الأمام عند توقف الحافلة فجأة؟', array['بسبب قوة تدفعهم للأمام','لأن أجسامهم تميل للاستمرار في الحركة','بسبب الجاذبية']::text[], '1'::jsonb, null, null, null, null, 'بسبب القصور الذاتي تستمر أجسامهم في الحركة.', null, null, 2) on conflict (id) do nothing;
