insert into questions (id, lesson_id, type, difficulty, prompt, options, answer, accepted, pairs, tolerance, unit, explanation, model_answer, image, sort) values ('g9_science_l1_q6', 'g9_science_l1', 'essay', 3, 'فسّر أهمية حزام الأمان في السيارة اعتمادًا على قانون نيوتن الأول.', null, null, null, null, null, null, null, 'عند التوقف المفاجئ يستمر جسم الراكب في الحركة للأمام بسبب القصور الذاتي، فيؤثر حزام الأمان بقوة توقفه وتمنعه من الاصطدام بالزجاج أو المقعد الأمامي.', null, 5) on conflict (id) do nothing;
insert into lessons (id, unit_id, title, objectives, explanation, examples, key_points, summary, video_url, book_page, sort, published) values ('g9_science_l2', 'g9_science_u1', 'قانون نيوتن الثاني', array['أنص على قانون نيوتن الثاني.','أحسب القوة والكتلة والتسارع باستخدام العلاقة ق = ك × ت.']::text[], 'ينص قانون نيوتن الثاني على أن: تسارع الجسم يتناسب طرديًا مع القوة المحصلة المؤثرة فيه، وعكسيًا مع كتلته، ويكون في اتجاه القوة المحصلة.
